public static class FeatureChecks {
    static T Field<T>(object value,string name){return (T)value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static IEnumerable<Control> All(Control root){yield return root;foreach(Control child in root.Controls)foreach(Control item in All(child))yield return item;}
    [StructLayout(LayoutKind.Sequential)]struct Mouse {public int X,Y;public uint Data,Flags,Time;public UIntPtr Extra;}
    [StructLayout(LayoutKind.Explicit)]struct Union {[FieldOffset(0)]public Mouse Mouse;}
    [StructLayout(LayoutKind.Sequential)]struct Input {public uint Type;public Union Value;}
    [DllImport("user32.dll")]static extern uint SendInput(uint count,Input[] input,int size);
    [DllImport("user32.dll")]static extern bool PostMessage(IntPtr window,uint message,IntPtr w,IntPtr l);
    static async Task SideButton(uint button,bool down){Input input=new Input();input.Type=0;input.Value.Mouse.Data=button;input.Value.Mouse.Flags=down?0x80U:0x100U;if(SendInput(1,new[]{input},Marshal.SizeOf(typeof(Input)))!=1)throw new Exception("Mouse fixture input was blocked.");await Task.Delay(100);}
    static void Render(Form form,string name,string output){using(Bitmap image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(output,name),System.Drawing.Imaging.ImageFormat.Png);}}
    public static async Task Run(string fixture,string output,Form form,TextBox field,Action<bool,string> check) {
        string root=Path.Combine(fixture,"features");Directory.CreateDirectory(root);PersonalizationStore personal=new PersonalizationStore(root);
        personal.Data.Words.Add(new WordRule {Heard="egg eye",Written="EhGI"});personal.Data.Words.Add(new WordRule {Heard="Sara",Written="Sarah"});personal.Data.Words.Add(new WordRule {Written="LocalFlow"});
        personal.Data.Snippets.Add(new Snippet {Trigger="my email",Text="alex@example.test"});personal.Data.Snippets.Add(new Snippet {Trigger="my email signature",Text="Thanks,\r\nAlex\r\nResearch & development"});personal.Save();await personal.FlushAsync();
        TextRules rules=new PersonalizationStore(root).Snapshot();check(rules.Correct("egg eye and Sara; Sarasotan") == "EhGI and Sarah; Sarasotan","Vocabulary exact phrases and whole word boundaries survive restart");check(rules.Guidance("").Contains("LocalFlow"),"Vocabulary words guide the local writing model");
        PreparedDictation prepared=rules.Prepare("send it to Sara at my email and use my email signature");string expanded=rules.Finish(prepared.Text,prepared);
        check(prepared.Inserts.Count==2&&expanded=="send it to Sarah at alex@example.test and use Thanks,\r\nAlex\r\nResearch & development","Snippets use longest triggers and retain exact multiline text");
        check(rules.Finish("The model removed a token.",prepared)==expanded,"Lost snippet marker safely restores original intended content");check(rules.Finish(prepared.Text+" "+prepared.Inserts.Keys.First(),prepared)==expanded,"Duplicated snippet marker cannot duplicate stored text");
        PreparedDictation literal=rules.Prepare("write the literal words my email and Sara");check(literal.Inserts.Count==0&&rules.Finish(literal.Text,literal).EndsWith("my email and Sara"),"Literal quoted words bypass snippet and vocabulary expansion");
        TextRules frozen=personal.Snapshot();personal.Data.Words[0].Written="Changed later";check(frozen.Correct("egg eye")=="EhGI","Active dictation holds a stable personalization snapshot");personal.Data.Words[0].Written="EhGI";
        using(PersonalizationWindow window=new PersonalizationWindow(personal,true)) {
            window.Show();All(window).OfType<Button>().Single(b=>b.Text=="Add snippet").PerformClick();check(Application.OpenForms.Cast<Form>().Count(f=>f is PersonalizationWindow)==1&&Field<Panel>(window,"editor").Visible,"Snippet editor stays inside the current section");Field<TextBox>(window,"first").Text="usual greeting";Field<TextBox>(window,"second").Text="Hello team,\r\nThanks!";All(window).OfType<Button>().Single(b=>b.Text=="Save").PerformClick();await personal.FlushAsync();
            check(new PersonalizationStore(root).Data.Snippets.Any(s=>s.Trigger=="usual greeting"&&s.Text=="Hello team,\r\nThanks!"),"Inline snippet editor persists exact multiline input");
            All(window).OfType<Button>().Single(b=>b.Text=="Add snippet").PerformClick();Field<TextBox>(window,"first").Text="usual greeting";Field<TextBox>(window,"second").Text="duplicate";All(window).OfType<Button>().Single(b=>b.Text=="Save").PerformClick();check(Field<Panel>(window,"editor").Visible&&personal.Data.Snippets.Count==3,"Duplicate phrase is rejected inline without overwriting a snippet");All(window).OfType<Button>().Single(b=>b.Text=="Cancel").PerformClick();Field<TextBox>(window,"search").Text="usual greeting";check(All(window).OfType<Button>().Count(b=>b.Text=="Edit")==1,"Snippet search filters cards");All(window).OfType<Button>().Single(b=>b.Text=="Copy").PerformClick();check(Clipboard.GetText()=="Hello team,\r\nThanks!","Snippet card copies exact content");All(window).OfType<Button>().Single(b=>b.Text=="Edit").PerformClick();Field<TextBox>(window,"second").Text="Updated";All(window).OfType<Button>().Single(b=>b.Text=="Save").PerformClick();check(personal.Data.Snippets.Single(v=>v.Trigger=="usual greeting").Text=="Updated","Snippet card edits the selected content");All(window).OfType<Button>().Single(b=>b.Text=="Delete").PerformClick();check(personal.Data.Snippets.Count==2,"Snippet card deletes only its own entry");window.Close();
        }
        Settings prefs=new Settings {SaveHistory=false,ShowBar=false,HoldMouse="Mouse 5",Cleanup="Medium",Sounds=true,MutePlayback=true};prefs.Save(root);Settings restored=Settings.Load(root);check(!restored.SaveHistory&&!restored.ShowBar&&restored.HoldMouse=="Mouse 5"&&restored.Cleanup=="Medium"&&restored.Sounds&&restored.MutePlayback,"Settings survive restart");
        using(SettingsWindow window=new SettingsWindow(prefs,new[]{"Ctrl + Shift + Space"})){Settings saved=null;window.Saved=value=>saved=value;window.Show();window.SelectSection("Style");ChoiceCard[] options=All(window).OfType<ChoiceCard>().Where(c=>StyleOptions.Names.Contains(c.Caption)).ToArray();check(options.Select(c=>c.Caption).SequenceEqual(StyleOptions.Names),"Style has exactly four clear cards");check(!All(window).OfType<ComboBox>().Any(c=>c.Items.Contains("Default")),"Style for and app overrides are removed");options.Single(c=>c.Caption=="Raw transcript").Checked=true;All(window).OfType<Button>().Single(b=>b.Text=="Save style").PerformClick();check(saved!=null&&!saved.Rewrite&&saved.Cleanup=="None"&&saved.Style=="Original transcript"&&!saved.SaveHistory&&saved.HoldMouse=="Mouse 5","Raw transcript bypasses AI and preserves unrelated preferences");
            ChoiceCard card=options.Single(c=>c.Caption=="Polish");PostMessage(card.Handle,0x201,new IntPtr(1),new IntPtr((25<<16)|25));PostMessage(card.Handle,0x202,IntPtr.Zero,new IntPtr((25<<16)|25));await Task.Delay(80);check(card.Checked&&options.Count(c=>c.Checked)==1,"Clicking a style card selects exactly one style");All(window).OfType<Button>().Single(b=>b.Text=="Save style").PerformClick();check(saved.Style=="Smart formatting"&&saved.Cleanup=="Medium"&&saved.Rewrite,"Polish enables cleanup and formatting");options.Single(c=>c.Caption=="Clean up").Checked=true;All(window).OfType<Button>().Single(b=>b.Text=="Save style").PerformClick();check(saved.Style=="Keep my wording"&&saved.Cleanup=="Light","Clean up selects minimal filler and grammar editing");
            options.Single(c=>c.Caption=="Custom").Checked=true;TextBox instructions=All(window).OfType<TextBox>().Single(t=>t.Multiline);instructions.Text="Use short sentences.";All(window).OfType<Button>().Single(b=>b.Text=="Save style").PerformClick();check(saved.Style=="Custom"&&saved.Custom==instructions.Text&&instructions.Visible&&instructions.Height>=200,"Custom reveals a large inline prompt box and saves instructions");saved.AppStyles.Add(new AppStyle {Application="chrome",Style="Professional",Cleanup="Light"});check(StyleRouting.Resolve(saved,"CHROME").Style=="Custom"&&StyleRouting.Resolve(saved,"other").Custom==instructions.Text,"One global style applies across every app even with legacy overrides");saved.Save(root);check(StyleOptions.Selected(Settings.Load(root))=="Custom","Global custom style survives restart");All(window).OfType<Button>().Single(b=>b.Text=="Save style").PerformClick();check(saved.AppStyles.Count==0,"Saving global style clears legacy app overrides");check(All(window).OfType<TabPage>().Select(t=>t.Text).SequenceEqual(new[]{"Style","Models","Shortcuts","System"}),"Settings has four focused sections");window.Close();}
        UsageStore usage=new UsageStore(root);usage.Record("one two three four","One two three four.",2,"chrome",DateTime.Now.Date.ToUniversalTime());usage.Record("five six","five six",1,"chrome",DateTime.Now.Date.AddDays(-1).ToUniversalTime());await usage.FlushAsync();UsageStore resumed=new UsageStore(root);check(resumed.Data.Words==6&&resumed.Data.Sessions==2&&resumed.WordsPerMinute==120&&resumed.Streak(DateTime.Today)==2,"Local usage totals, speaking rate and streak survive restart");string stats=File.ReadAllText(Path.Combine(root,"usage.json"));check(!stats.Contains("one two")&&!stats.Contains("five six"),"Usage stores counts without spoken text");resumed.Record("untimed sample","",0,"Other",DateTime.UtcNow);check(resumed.WordsPerMinute==120,"Untimed text does not distort speaking speed");resumed.Clear();await resumed.FlushAsync();check(new UsageStore(root).Data.Sessions==0,"Reset usage clears saved statistics");
        HistoryStore history=new HistoryStore(root);history.Add("um please send the report tomorrow","Please send the report tomorrow.","Keep my wording");await history.FlushAsync();
        Settings hubPrefs=new Settings();Func<ModelWindow> factory=()=>new ModelWindow(fixture,hubPrefs,new ComputerSpecs {RamBytes=128L*1073741824,GpuBytes=12L*1073741824,Gpu="Fixture GPU"});
        using(HubWindow hub=new HubWindow(history,personal,usage,()=>hubPrefs,value=>hubPrefs=value,factory,new[]{"Ctrl + Shift + Space"},"Ctrl + Shift + E")) {
            hub.Show();hub.SetStatus("Ready · Ctrl + Shift + Space");await Task.Delay(120);check(Field<FlowLayoutPanel>(hub,"navigation").Controls.OfType<Button>().Select(b=>b.Text).SequenceEqual(new[]{"Home","History","Snippets","Vocabulary","Settings"}),"Sidebar has five focused sections with Features and Scratchpad removed");
            foreach(string page in new[]{"Home","Vocabulary","Snippets","Settings","Style","Models","History"}){hub.Navigate(page);await Task.Delay(70);check(Field<Form>(hub,"page")!=null,"Hub navigation works: "+page);Render(hub,"hub-"+page.ToLowerInvariant()+".png",output);}
            hub.Navigate("History");check(!All(Field<Form>(hub,"page")).OfType<Button>().Any(b=>b.Text.Contains("Home"))&&!Field<Panel>(hub,"content").Controls.OfType<Panel>().Any(),"History has no top back or Home button");
            for(int i=0;i<7;i++)history.Add("Synthetic dictation "+i,"Synthetic dictation "+i,"Clean up");history.Add("Source","Summary","Summarize","Source");hub.Navigate("Home");check(All(hub).OfType<Button>().Count(b=>b.Text=="Copy")==5,"Home shows only the five latest dictations");
            hub.Navigate("Models");ModelWindow models=All(hub).OfType<ModelWindow>().Single();check(!models.TopLevel&&models.Visible&&Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel&&f is ModelWindow)==0,"Models remain embedded in Settings without a popup");check(All(models).OfType<Label>().Any(l=>l.Text.Contains("tdt-0.6b-v2-q8_0.gguf"))&&All(models).OfType<Label>().Any(l=>l.Text.Contains("Qwen3-4B-Instruct-2507-Q3_K_S.gguf")),"Models displays both exact model names and roles");bool applied=false;models.ApplyModels=pair=>Task.FromResult(applied=pair.Id=="balanced");All(models).OfType<Button>().Single(b=>b.Text=="Load models").PerformClick();for(int i=0;i<150&&!applied;i++)await Task.Delay(100);check(applied&&models.Visible&&!models.IsDisposed,"Installed models can be verified and applied without closing Settings");
            hub.ClientSize=new Size(950,740);hub.Navigate("Style");hub.PerformLayout();SettingsWindow settings=Field<Form>(hub,"page") as SettingsWindow;check(settings!=null&&All(settings).OfType<Button>().Single(b=>b.Text=="Save style").Right<=settings.ClientSize.Width,"Settings fit the minimum hub size");Render(hub,"hub-style-minimum.png",output);hub.Navigate("Snippets");All(hub).OfType<Button>().Single(b=>b.Text=="Add snippet").PerformClick();Render(hub,"hub-snippet-editor-minimum.png",output);hub.Close();
        }
        using(Pill bar=new Pill()){bar.Persistent=true;bar.Available=true;int starts=0;bar.Start=()=>starts++;bar.ShowIdle();await Task.Delay(60);check(bar.Idle&&bar.ResultReady==false&&bar.Width<=247&&bar.Height<=38,"Compact bar shows idle dictation controls");Render(bar,"flow-bar-preview.png",output);PostMessage(bar.Handle,0x201,new IntPtr(1),new IntPtr((19<<16)|80));PostMessage(bar.Handle,0x202,IntPtr.Zero,new IntPtr((19<<16)|80));await Task.Delay(60);check(starts==1,"Persistent bar starts dictation with one click");FocusTarget focus=FocusTarget.Capture();Point origin=bar.Location;PostMessage(bar.Handle,0x201,new IntPtr(1),new IntPtr((19<<16)|12));PostMessage(bar.Handle,0x200,new IntPtr(1),new IntPtr((40<<16)|52));PostMessage(bar.Handle,0x202,IntPtr.Zero,new IntPtr((19<<16)|12));await Task.Delay(80);check(bar.Pinned&&bar.Location!=origin&&focus.MatchesCurrent(),"Bar drags freely without taking focus or triggering dictation");Point pinned=bar.Location;bar.Place(form.Handle);check(bar.Location==pinned,"Pinned bar position survives field changes");bar.Prepare("Listening",true);bar.UpdateTranscript("Please send the report to Sarah tomorrow.");bar.Reveal();check(bar.TranscriptText.Contains("Sarah")&&Field<System.Windows.Forms.Timer>(bar,"animation").Enabled,"Recording bar shows recognized text and animates");Render(bar,"recording-pill.png",output);bar.ShowProcessing(true);await Task.Delay(100);check(bar.Processing&&!bar.Recording&&bar.TranscriptText.Contains("Sarah")&&Field<System.Windows.Forms.Timer>(bar,"animation").Enabled,"AI polishing keeps the transcript visible with an animation");Render(bar,"polishing-pill.png",output);bar.ShowResult("Fixture",false,true,form.Handle);bar.Conceal();check(bar.Idle&&!bar.ResultReady&&!bar.Processing,"Dismissing a result returns to the permanent bar");bar.Persistent=false;bar.Conceal();}
        using(ActivityGrid grid=new ActivityGrid(usage)){using(Form calendar=new Form {ClientSize=new Size(640,200)}){calendar.Controls.Add(grid);calendar.Show();Rectangle cell=grid.DayBounds(DateTime.Today);int x=cell.Left+3,y=cell.Top+3;typeof(Control).GetMethod("OnMouseMove",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(grid,new object[]{new MouseEventArgs(MouseButtons.None,0,x,y,0)});check(grid.HighlightedDate==DateTime.Today,"Activity hover identifies the exact date");PostMessage(grid.Handle,0x201,new IntPtr(1),new IntPtr((y<<16)|x));PostMessage(grid.Handle,0x202,IntPtr.Zero,new IntPtr((y<<16)|x));PostMessage(grid.Handle,0x2a3,IntPtr.Zero,IntPtr.Zero);await Task.Delay(50);check(grid.HighlightedDate==DateTime.Today,"Activity click keeps a date highlighted after the pointer leaves");Render(calendar,"activity-detail-preview.png",output);calendar.Close();}}
        form.Activate();field.Focus();await Task.Delay(80);int down=0,up=0;using(HoldMouseInput mouse=new HoldMouseInput(SynchronizationContext.Current)) {mouse.CanStart=()=>true;mouse.Down=()=>down++;mouse.Up=()=>up++;mouse.Configure("Mouse 4");check(mouse.Installed,"Native mouse hold-to-talk hook installs");await SideButton(1,true);await SideButton(1,false);check(down==1&&up==1,"Mouse 4 press and release dispatch exactly one recording cycle");await SideButton(2,true);await SideButton(2,false);check(down==1&&up==1,"Other mouse buttons leave hold-to-talk unchanged");mouse.Configure("Mouse 5");await SideButton(2,true);await SideButton(2,false);check(down==2&&up==2,"Mouse 5 can be configured for hold-to-talk");mouse.Configure("Off");check(!mouse.Installed,"Disabling hold-to-talk removes the native hook");}
        bool priorMute=PlaybackMute.CurrentMuted();using(PlaybackMute mute=new PlaybackMute())check(PlaybackMute.CurrentMuted(),"Optional playback mute sets the default device mute state");check(PlaybackMute.CurrentMuted()==priorMute,"Playback mute restores the original device state");
        await personal.FlushAsync();await usage.FlushAsync();
    }
    public static async Task Models(Models models,Action<bool,string> check) {
        string raw="um hello Sarah please review the report tomorrow thanks";string none=await models.Rewrite(raw,"Professional","",CancellationToken.None,"","None");check(none==raw,"Cleanup None returns original transcript without rewriting");
        string medium=await models.Rewrite("um hey Sarah so the meeting is on Tuesday at two pm and I do not want to cancel it please keep the meeting on Tuesday","Keep my wording","",CancellationToken.None,"","Medium");check(medium.Contains("Sarah")&&medium.Contains("Tuesday")&&!medium.ToLowerInvariant().Contains("cancel the meeting"),"Medium cleanup preserves names, day and intended meeting");
        PersonalData data=new PersonalData();data.Snippets.Add(new Snippet {Trigger="my email",Text="alex@example.test"});TextRules rules=new TextRules(data);PreparedDictation prepared=rules.Prepare("please send the report to my email tomorrow");string edited=await models.Rewrite(prepared.Text,"Keep my wording","",CancellationToken.None);string expanded=rules.Finish(edited,prepared);check(expanded.Contains("alex@example.test")&&expanded.Contains("tomorrow")&&!expanded.Contains("LF_SNIP_"),"Local AI cleanup expands a stored snippet without changing it");
    }
}
